<?php namespace Tests\Unit; use App\Services\{ContentTransformer,ContentSanitizer};use PHPUnit\Framework\TestCase;class ContentConversionTest extends TestCase {public function test_vc_and_legacy_scripts_are_not_rendered():void{$x=(new ContentTransformer)->transform('[vc_row][vc_column_text]<h2>Été</h2>[/vc_column_text][vc_message]Info[/vc_message][vc_widget_sidebar][/vc_column][/vc_row]');$z=(new ContentSanitizer)->sanitize($x['html'].'<script>alert(1)</script><iframe src="https://ads.example/x"></iframe>');$this->assertStringContainsString('<aside',$z['html']);$this->assertStringNotContainsString('vc_',$z['html']);$this->assertStringNotContainsString('<script',$z['html']);$this->assertContains('script',$z['removed']);$this->assertContains('iframe',$z['removed']);}public function test_it_removes_both_legacy_upload_path_spellings():void{$z=(new ContentSanitizer)->sanitize('<img src="https://top-halal.fr/wp-content/uploads/a.jpg"><img src="https://top-halal.fr/wp-contenu/uploads/b.jpg">');$this->assertSame('',$z['html']);$this->assertSame(['legacy_image','legacy_image'],$z['removed']);}}
